package com.adib.maintenance;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.lang.reflect.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={24,28,35})
public class EmployeeChatsTest {
 Context c;JSONObject oldUser;TaskReminderActions.Transport old;
 @Before public void before()throws Exception{c=RuntimeEnvironment.getApplication();oldUser=AccountSession.user;AccountSession.user=new JSONObject().put("id","a").put("name","Ilqar").put("role","admin");old=EmployeeChats.transport;EmployeeChats.owner="";EmployeeChats.refreshing=false;EmployeeChats.waiters.clear();EmployeeChats.chats.clear();EmployeeChats.transport=(m,p,b)->{if(p.equals("/api/employee-chats"))return new JSONObject().put("available",true).put("employees",new JSONArray().put(new JSONObject().put("id","b").put("name","Huseyn"))).put("threads",new JSONArray().put(new JSONObject().put("peerId","b").put("peerName","Huseyn").put("unreadCount",1).put("lastMessage",msg("m1","Hi"))));if(m.equals("POST"))return new JSONObject().put("message",msg("m2",b.optString("text")));return new JSONObject().put("peer",new JSONObject().put("id","b").put("name","Huseyn")).put("messages",new JSONArray().put(msg("m1","Hi")));};}
 @After public void after(){EmployeeChats.transport=old;EmployeeChats.owner="";EmployeeChats.chats.clear();EmployeeChats.waiters.clear();EmployeeChats.operations.clear();AccountSession.user=oldUser;}
 JSONObject msg(String id,String text)throws Exception{return new JSONObject().put("id",id).put("senderId","b").put("senderName","Huseyn").put("text",text).put("createdAt",1700000000000L);}
 void waitFor(AtomicBoolean done)throws Exception{long until=System.currentTimeMillis()+5000;while(!done.get()&&System.currentTimeMillis()<until){Thread.sleep(10);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertTrue(done.get());}
 @Test public void directoryMergesWithTaskDiscussionsAndLoadedMessagesHaveISOTime()throws Exception{AtomicBoolean done=new AtomicBoolean();EmployeeChats.refresh(c,(r,e)->done.set(r!=null));waitFor(done);JSONArray rows=EmployeeChats.merge(c,new JSONArray().put(new JSONObject().put("taskId","task")));assertEquals(2,rows.length());assertEquals(1,EmployeeChats.tasks(rows).length());assertEquals("employee:b",rows.getJSONObject(1).getString("taskId"));done.set(false);EmployeeChats.load(c,"employee:b",(r,e)->done.set(r!=null));waitFor(done);assertTrue(EmployeeChats.chats.get("b").optBoolean("loaded"));assertTrue(EmployeeChats.chats.get("b").getJSONArray("comments").getJSONObject(0).getString("createdAt").endsWith("Z"));assertEquals(0,EmployeeChats.chats.get("b").getInt("unreadCount"));}
 @Test public void failedSendRetainsOperationAndRetryReusesIt()throws Exception{java.util.List<String> ops=new java.util.ArrayList<>();EmployeeChats.transport=(m,p,b)->{ops.add(b.getString("operationId"));if(ops.size()==1)throw new java.io.IOException("offline");return new JSONObject().put("message",msg("sent",b.optString("text")));};AtomicBoolean done=new AtomicBoolean();EmployeeChats.send(c,"employee:b","Once",(r,e)->done.set(r==null));waitFor(done);done.set(false);EmployeeChats.send(c,"employee:b","Once",(r,e)->done.set(r!=null));waitFor(done);assertEquals(2,ops.size());assertEquals(ops.get(0),ops.get(1));}
 @Test public void changingAccountClearsPrivateEmployeeData()throws Exception{EmployeeChats.scope(c);EmployeeChats.chats.put("b",EmployeeChats.thread("b","Huseyn",new JSONArray()));String prior=EmployeeChats.owner;AccountSession.user=new JSONObject().put("id","other").put("name","Other");/* production suffix is account-scoped; test mode intentionally uses legacy suffix */EmployeeChats.owner=prior+":old";EmployeeChats.scope(c);assertTrue(EmployeeChats.chats.isEmpty());assertEquals(0,EmployeeChats.peers(c).length());}
 Object call(MainActivity a,String method,Class<?>[] types,Object...args)throws Exception{Method m=MainActivity.class.getDeclaredMethod(method,types);m.setAccessible(true);return m.invoke(a,args);}void set(MainActivity a,String name,Object v)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);f.set(a,v);}Object get(MainActivity a,String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(a);}
 @Test public void lowerNavigationIncludesAccessibleDiscussionsEntry()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();LinearLayout root=new LinearLayout(a);set(a,"root",root);call(a,"appendHomeNav",new Class[]{boolean.class},true);View nav=root.findViewWithTag("home-navigation"),entry=root.findViewWithTag("home-nav:7");assertNotNull(nav);assertNotNull(entry);assertEquals("Müzakirələr",entry.getContentDescription().toString());}
 @Test public void fullscreenScreenHasTabsAndEmployeeChatHidesTaskLinkAndImagePicker()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();set(a,"chatRequestRunning",true);a.getPreferences(0).edit().putString("chat_threads_cache","[]").commit();call(a,"showChat",new Class[]{});AtomicBoolean done=new AtomicBoolean();EmployeeChats.refresh(a,(r,e)->done.set(r!=null));waitFor(done);EmployeeChats.load(a,"employee:b",(r,e)->{});Thread.sleep(50);Shadows.shadowOf(Looper.getMainLooper()).idle();set(a,"chatThreads",EmployeeChats.merge(a,new JSONArray()));set(a,"activeChatTaskId","employee:b");set(a,"chatConversationOpen",true);call(a,"showChatPage",new Class[]{});View screen=(View)get(a,"chatScreenRoot");assertEquals("discussions-screen",screen.getTag());assertEquals(Boolean.TRUE,get(a,"chatScreenOpen"));assertNotNull(screen.findViewWithTag("home-navigation"));View page=(View)get(a,"chatListPage");assertNotNull(page.findViewWithTag("discussion-tabs"));assertEquals(View.GONE,((View)get(a,"chatTaskLink")).getVisibility());EditText composer=(EditText)get(a,"chatComposer");assertEquals(4000,((android.text.InputFilter.LengthFilter)composer.getFilters()[0]).getMax());LinearLayout slot=((View)get(a,"chatConversationPage")).findViewWithTag("chat-image-picker-slot");assertEquals(0,slot.getChildCount());assertEquals(screen,a.findViewById(android.R.id.content).findViewWithTag("discussions-screen"));}
}
